<#
.SYNOPSIS
    Windows GUI for the system information report.

.DESCRIPTION
    Starts elevated automatically (UAC prompt on launch). Admin rights are
    needed to read SMART/wear data for SSD health.

    Label printing uses QZ Tray (https://qz.io) running on a shared host.
    Run Generate-QzCert.ps1 once to create the signing credentials, then
    paste the values into the two constants near the top of this file and
    recompile.

.NOTES
    To convert this to a standalone .exe (no PowerShell window):
        Install-Module ps2exe -Scope CurrentUser
        Invoke-ps2exe .\SystemInfo-GUI.ps1 .\SystemInfo.exe -noConsole -requireAdmin
#>

# -- Auto-elevate --------------------------------------------------------------
$_isAdminCheck = $false
try {
    $_id = [System.Security.Principal.WindowsIdentity]::GetCurrent()
    $_pr = New-Object System.Security.Principal.WindowsPrincipal($_id)
    $_isAdminCheck = $_pr.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
} catch { }

if (-not $_isAdminCheck) {
    try {
        $_exePath = $null
        try {
            $_main = [System.Diagnostics.Process]::GetCurrentProcess().MainModule
            if ($_main) { $_exePath = $_main.FileName }
        } catch {}

        $_isPwshHost = ($_exePath -match '\\powershell(_ise)?\.exe$' -or $_exePath -match '\\pwsh\.exe$')

        if ($_exePath -and ($_exePath -like '*.exe') -and -not $_isPwshHost) {
            Start-Process -FilePath $_exePath -Verb RunAs | Out-Null
            exit
        } else {
            $_scriptPath = $null
            if ($PSCommandPath)                   { $_scriptPath = $PSCommandPath }
            elseif ($MyInvocation.MyCommand.Path) { $_scriptPath = $MyInvocation.MyCommand.Path }

            if ($_scriptPath) {
                Start-Process -FilePath 'powershell.exe' `
                    -ArgumentList @('-NoProfile','-NonInteractive','-WindowStyle','Hidden',
                                    '-ExecutionPolicy','Bypass','-File',"`"$_scriptPath`"") `
                    -Verb RunAs -WindowStyle Hidden | Out-Null
                exit
            }
        }
    } catch {
        Add-Type -AssemblyName System.Windows.Forms
        [System.Windows.Forms.MessageBox]::Show(
            "Continuing without administrator rights. SSD health values will not be available.",
            "Not elevated",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
    }
}

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

# -- AppDir detection (works for .ps1 and ps2exe .exe) -------------------------
$script:AppDir = $null
if ($PSScriptRoot)                                  { $script:AppDir = $PSScriptRoot }
elseif ($MyInvocation.MyCommand.Path)               { $script:AppDir = Split-Path -Parent $MyInvocation.MyCommand.Path }
else {
    try {
        $main = [System.Diagnostics.Process]::GetCurrentProcess().MainModule
        if ($main -and $main.FileName) { $script:AppDir = Split-Path -Parent $main.FileName }
    } catch { }
}
if (-not $script:AppDir) { $script:AppDir = (Get-Location).Path }

# -- Application version + GitHub update source --------------------------------
$script:AppVersion  = '1.0.0'
$script:GitHubOwner = ''   # e.g. 'myusername'
$script:GitHubRepo  = ''   # e.g. 'SystemInfo-GUI'

# ==============================================================================
#  EMBEDDED IsMyLcdOK_x64.exe  (NirSoft -- display/LCD tester. Extracted to
#  %TEMP% and launched when the Test Display button is clicked.)
# ==============================================================================
$script:EmbeddedIsMyLcdOKB64 = ''

# ==============================================================================
#  EMBEDDED BatteryInfoView.exe  (NirSoft) -- battery probe used by
#  Get-BatteryHealthInfo. Extracted to %TEMP% on first use; called with /sxml
#  to produce a parseable XML report.
# ==============================================================================
$script:EmbeddedBivB64 = ''

# ==============================================================================
#  EMBEDDED kb.exe  (keyboard tester  -  base64 of the original kb.exe binary,
#  extracted to %TEMP% on first use so the .exe is fully self-contained)
# ==============================================================================
$script:EmbeddedKbExeB64 = ''

# ==============================================================================
#  DATA GATHERING
# ==============================================================================
function Get-Safe {
    param([scriptblock]$Script, [string]$Default = 'Unknown')
    try {
        $v = & $Script
        if ($null -eq $v -or "$v".Trim() -eq '') { return $Default }
        return $v
    } catch { return $Default }
}

$script:PKEY_BtLmp = '{83DA6326-97A6-4088-9453-A1923F573B29} 12'

function Get-DiskHealthPercent {
    param($PhysicalDisk)
    try {
        $rel = $PhysicalDisk | Get-StorageReliabilityCounter -ErrorAction Stop
        if ($rel -and $null -ne $rel.Wear) {
            return [Math]::Max(0, [Math]::Min(100, 100 - [int]$rel.Wear))
        }
    } catch { }
    try {
        $rel2 = Get-CimInstance -Namespace root\Microsoft\Windows\Storage `
            -ClassName MSFT_StorageReliabilityCounter -ErrorAction Stop |
            Where-Object { $_.DeviceId -eq $PhysicalDisk.DeviceId } | Select-Object -First 1
        if ($rel2 -and $null -ne $rel2.Wear) {
            return [Math]::Max(0, [Math]::Min(100, 100 - [int]$rel2.Wear))
        }
    } catch { }
    return $null
}

function Test-IsAdmin {
    try {
        $id = [System.Security.Principal.WindowsIdentity]::GetCurrent()
        $p  = New-Object System.Security.Principal.WindowsPrincipal($id)
        return $p.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch { return $false }
}

function Test-IsLaptop {
    $portable = @(8, 9, 10, 11, 12, 14, 30, 31, 32)
    try {
        $enc = Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction Stop
        foreach ($e in $enc) {
            foreach ($t in $e.ChassisTypes) {
                if ($portable -contains [int]$t) { return $true }
            }
        }
    } catch { }
    try {
        $bat = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue
        if ($bat) { return $true }
    } catch { }
    return $false
}

# ---- Embedded QRCoder (offline QR generation) ----------------------------
$script:EmbeddedQRCoderB64 = ''

function Get-QRCoderAssembly {
    # Loads the embedded QRCoder library in-memory (no temp file, no internet).
    # QRCoder 1.6.0 (net40, MIT) — generates QR codes entirely offline; the old
    # path POSTed the specs to api.qrserver.com just to render an image.
    if ($script:QRCoderAsm) { return $script:QRCoderAsm }
    if (-not $script:EmbeddedQRCoderB64 -or $script:EmbeddedQRCoderB64 -like '*PLACEHOLDER*') {
        throw "QRCoder library is not embedded in this build."
    }
    $bytes = [Convert]::FromBase64String($script:EmbeddedQRCoderB64)
    $script:QRCoderAsm = [Reflection.Assembly]::Load($bytes)
    return $script:QRCoderAsm
}

function Get-SpecsJson {
    # Builds a compact, structured JSON payload from the current report for the
    # "Show QR Code" transfer. Keyed by canonical field names so a consuming app
    # can parse it reliably (vs the old loose "Property: Value" text dump).
    param($Report)
    if (-not $Report) { return $null }
    $clean = {
        param($s)
        ((([string]$s) -replace "`r?`n", '; ') -replace '\s*;\s*;', ';').Trim().TrimEnd(';').Trim()
    }
    $map = [ordered]@{
        'Manufacturer'     = 'manufacturer'
        'Model'            = 'model'
        'Serial Number'    = 'serial'
        'CPU'              = 'cpu'
        'Dedicated GPU'    = 'gpuDedicated'
        'Integrated GPU'   = 'gpuIntegrated'
        'RAM'              = 'ram'
        'Operating System' = 'os'
        'Battery Health'   = 'battery'
        'Screen size'           = 'screenSize'
        'Screen max resolution' = 'resolution'
        'Touchscreen'           = 'touch'
        'WWAN'                  = 'wwan'
    }
    $fields = [ordered]@{}
    foreach ($row in $Report) {
        if ($map.Contains($row.Property)) {
            $v = & $clean $row.Value
            if ($v) { $fields[$map[$row.Property]] = $v }
        }
    }
    $storage = @()
    foreach ($row in $Report) {
        if ($row.Property -like 'Storage*') {
            $v = & $clean $row.Value
            if ($v) { $storage += $v }
        }
    }
    if ($storage.Count) { $fields['storage'] = @($storage) }
    if ($fields.Count -eq 0) { return $null }
    $payload = [ordered]@{ t = 'sysinfo'; v = 1; fields = $fields }
    return ($payload | ConvertTo-Json -Depth 5 -Compress)
}


function Get-EmbeddedBatteryInfoViewPath {
    # Extracts the embedded BatteryInfoView.exe to %TEMP%\SystemInfo-BIV.exe
    # on first use, reusing the cached copy if its size already matches.
    if (-not $script:EmbeddedBivB64 -or $script:EmbeddedBivB64 -like '*PLACEHOLDER*') { return $null }
    $bytes  = [Convert]::FromBase64String($script:EmbeddedBivB64)
    $target = Join-Path $env:TEMP 'SystemInfo-BIV.exe'
    $needWrite = $true
    if (Test-Path -LiteralPath $target) {
        try { if ((Get-Item -LiteralPath $target).Length -eq $bytes.Length) { $needWrite = $false } } catch {}
    }
    if ($needWrite) { [IO.File]::WriteAllBytes($target, $bytes) }
    return $target
}

function Get-EmbeddedIsMyLcdOKPath {
    if (-not $script:EmbeddedIsMyLcdOKB64 -or $script:EmbeddedIsMyLcdOKB64 -like '*PLACEHOLDER*') { return $null }
    $bytes  = [Convert]::FromBase64String($script:EmbeddedIsMyLcdOKB64)
    $target = Join-Path $env:TEMP 'SystemInfo-IsMyLcdOK.exe'
    $needWrite = $true
    if (Test-Path -LiteralPath $target) {
        try { if ((Get-Item -LiteralPath $target).Length -eq $bytes.Length) { $needWrite = $false } } catch {}
    }
    if ($needWrite) { [IO.File]::WriteAllBytes($target, $bytes) }
    return $target
}
function Get-BatteryHealthInfo {
    # Runs embedded BatteryInfoView.exe with /sxml and parses the result.
    # BatteryInfoView's XML has <item> blocks each containing a <description>
    # (field name) plus one <value> per battery slot (empty slot = no battery).
    # We sum the capacities across populated slots and recompute the health %.
    if ($script:BatteryHealthCache) { return $script:BatteryHealthCache }

    $result = [PSCustomObject]@{
        Percent          = $null
        FullCapMwh       = $null
        DesignCapMwh     = $null
        CurrentChargePct = $null
        Diag             = $null
    }

    $biv = Get-EmbeddedBatteryInfoViewPath
    if (-not $biv) {
        $result.Diag = 'BatteryInfoView payload missing from build'
        $script:BatteryHealthCache = $result
        return $result
    }

    $xmlPath = Join-Path $env:TEMP ("SystemInfo-BIV-" + [Guid]::NewGuid().ToString('N') + ".xml")
    try {
        $proc = Start-Process -FilePath $biv -ArgumentList @('/sxml', "`"$xmlPath`"") `
                              -WindowStyle Hidden -PassThru -Wait
        if (-not (Test-Path -LiteralPath $xmlPath)) {
            $result.Diag = "BatteryInfoView did not produce output (exit $($proc.ExitCode))"
            $script:BatteryHealthCache = $result
            return $result
        }

        $doc = New-Object System.Xml.XmlDocument
        $doc.Load($xmlPath)

        # description -> [non-empty values]
        $fields = @{}
        foreach ($item in @($doc.SelectNodes('//item'))) {
            $desc = $item.SelectSingleNode('description')
            if (-not $desc -or -not $desc.InnerText) { continue }
            $vals = @()
            foreach ($v in @($item.SelectNodes('value'))) {
                if ($v.InnerText -and $v.InnerText.Trim()) { $vals += $v.InnerText.Trim() }
            }
            $fields[$desc.InnerText.Trim()] = $vals
        }

        $designVals = $fields['Designed Capacity']
        $fullVals   = $fields['Full Charged Capacity']
        $healthVals = $fields['Battery Health']
        $chargeVals = $fields['Current Capacity (in %)']

        # Capacities formatted like "56,000 mWh"  -  strip non-digits then sum.
        if ($designVals -and $fullVals) {
            $design = 0L; $fullC = 0L
            foreach ($s in $designVals) {
                $n = ($s -replace '[^\d]','')
                if ($n) { $design += [int64]$n }
            }
            foreach ($s in $fullVals) {
                $n = ($s -replace '[^\d]','')
                if ($n) { $fullC += [int64]$n }
            }
            if ($design -gt 0 -and $fullC -gt 0) {
                $result.DesignCapMwh = [int]$design
                $result.FullCapMwh   = [int]$fullC
                $result.Percent      = [Math]::Round(($fullC / $design) * 100, 1)
            }
        }

        # Fall back to the precomputed "Battery Health" % if we got it
        # but capacities were missing.
        if ($result.Percent -eq $null -and $healthVals) {
            $m = [regex]::Match($healthVals[0], '([0-9]+(?:\.[0-9]+)?)')
            if ($m.Success) { $result.Percent = [double]$m.Groups[1].Value }
        }

        if ($chargeVals) {
            $m = [regex]::Match($chargeVals[0], '([0-9]+(?:\.[0-9]+)?)')
            if ($m.Success) { $result.CurrentChargePct = [int][double]$m.Groups[1].Value }
        }

        if ($result.Percent -eq $null -and $result.CurrentChargePct -eq $null) {
            $result.Diag = 'BatteryInfoView ran but reported no battery data'
        }
    } catch {
        $result.Diag = "BatteryInfoView error: $($_.Exception.Message)"
    } finally {
        Remove-Item -LiteralPath $xmlPath -ErrorAction SilentlyContinue
    }

    $script:BatteryHealthCache = $result
    return $result
}

function Format-BatteryRowValue {
    $info = Get-BatteryHealthInfo
    if ($info.Percent -ne $null -and $info.FullCapMwh -ne $null) {
        return ("{0}% ({1:N0} / {2:N0} mWh)" -f $info.Percent, $info.FullCapMwh, $info.DesignCapMwh)
    }
    if ($info.Percent -ne $null) {
        return ("{0}%" -f $info.Percent)
    }
    if ($info.CurrentChargePct -ne $null) {
        return ("Health unknown; current charge: {0}%" -f $info.CurrentChargePct)
    }
    if ($info.Diag) { return "N/A -- $($info.Diag)" }
    return 'N/A (no battery data)'
}

function Start-ParallelFetches {
    # Kicks off the given scriptblocks in a RunspacePool and returns a job map.
    # Each job is fetched via Get-Fetch (which blocks until that job is done).
    param([hashtable]$Map)
    $maxParallel = [Math]::Min([Math]::Max($Map.Count, 1), 8)
    $pool = [RunspaceFactory]::CreateRunspacePool(1, $maxParallel)
    $pool.ApartmentState = 'STA'
    $pool.Open()
    $jobs = @{ '__pool' = $pool }
    foreach ($name in $Map.Keys) {
        $ps = [PowerShell]::Create()
        $ps.RunspacePool = $pool
        [void]$ps.AddScript($Map[$name])
        $jobs[$name] = @{ PS = $ps; Async = $ps.BeginInvoke(); Done = $false; Result = $null }
    }
    return $jobs
}

function Get-Fetch {
    # Await a single fetch and return the unwrapped result.
    param($Jobs, [string]$Name)
    $j = $Jobs[$Name]
    if ($null -eq $j) { return $null }
    if ($j.Done) { return $j.Result }
    try {
        $r = $j.PS.EndInvoke($j.Async)
        if ($r -is [System.Collections.IList]) {
            if     ($r.Count -eq 0) { $j.Result = $null }
            elseif ($r.Count -eq 1) { $j.Result = $r[0] }
            else                    { $j.Result = $r }
        } else {
            $j.Result = $r
        }
    } catch {
        $j.Result = $null
    }
    try { $j.PS.Dispose() } catch {}
    $j.Done = $true
    return $j.Result
}

function Close-Fetches {
    param($Jobs)
    if (-not $Jobs) { return }
    foreach ($k in @($Jobs.Keys)) {
        if ($k -eq '__pool') { continue }
        $j = $Jobs[$k]
        if (-not $j.Done) {
            try { $j.PS.Stop() } catch {}
            try { $j.PS.Dispose() } catch {}
        }
    }
    try { $Jobs['__pool'].Close() } catch {}
    try { $Jobs['__pool'].Dispose() } catch {}
}

function Format-LicenseStatus {
    param($Lic)
    if (-not $Lic) { return 'Not activated' }
    switch ([int]$Lic.LicenseStatus) {
        1 { 'Activated' }          0 { 'Unlicensed' }
        2 { 'Initial grace' }      3 { 'Additional grace' }
        4 { 'Non-genuine grace' }  5 { 'Notification (not activated)' }
        6 { 'Extended grace' }
        default { "Status $($Lic.LicenseStatus)" }
    }
}

function Get-SystemReport {
    $script:IsAdmin  = Test-IsAdmin
    $script:IsLaptop = Test-IsLaptop

    # Ensure BatteryInfoView is on disk before the parallel battery probe runs
    $null = Get-EmbeddedBatteryInfoViewPath

    # Build the parallel-fetch map (slow CIM/PnP/Net queries only)
    $fetchMap = @{
        cs          = { Get-CimInstance -ClassName Win32_ComputerSystem }
        bios        = { Get-CimInstance -ClassName Win32_BIOS }
        cpu         = { Get-CimInstance Win32_Processor | Select-Object -First 1 }
        gpus        = { Get-CimInstance Win32_VideoController }
        sounds      = {
            Get-CimInstance Win32_SoundDevice -ErrorAction SilentlyContinue |
                Where-Object { $_.Status -eq 'OK' -and $_.Name -notmatch 'Virtual|Remote' }
        }

        memArr      = { Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | Select-Object -First 1 }
        memMods     = { Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue | Sort-Object DeviceLocator }
        wifiAdapter = {
            Get-NetAdapter -ErrorAction SilentlyContinue |
                Where-Object {
                    ($_.PhysicalMediaType -eq 'Native 802.11' -or
                     $_.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11') -and
                    $_.InterfaceDescription -notmatch 'Virtual|Bluetooth|WWAN'
                } | Select-Object -First 1
        }
        wifiRadio   = {
            try {
                $out  = netsh wlan show drivers 2>$null
                $line = $out | Where-Object { $_ -match 'Radio types supported' } | Select-Object -First 1
                if ($line) { ($line -split ':', 2)[1].Trim() } else { '' }
            } catch { '' }
        }
        btDevice    = {
            Get-PnpDevice -Class Bluetooth -PresentOnly -ErrorAction SilentlyContinue |
                Where-Object { $_.Status -eq 'OK' -and $_.FriendlyName -match 'Bluetooth' -and
                               $_.FriendlyName -notmatch 'Enumerator' } | Select-Object -First 1
        }
        wwanAdapter = {
            Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.PhysicalMediaType -eq 'Wireless WAN' -or
                    $_.InterfaceDescription -match 'WWAN|Mobile Broadband|Cellular|\bLTE\b|\b5G\b|\b4G\b'
                } | Select-Object -First 1
        }
        os          = { Get-CimInstance Win32_OperatingSystem }
        license     = {
            Get-CimInstance -Query ("SELECT LicenseStatus FROM SoftwareLicensingProduct " +
                "WHERE ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' " +
                "AND PartialProductKey IS NOT NULL") -ErrorAction SilentlyContinue |
                Select-Object -First 1
        }
        pnpProblems = {
            Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.ConfigManagerErrorCode -gt 0 -and
                    $_.ConfigManagerErrorCode -ne 22 -and
                    $_.Name
                }
        }
    }
    if ($script:IsLaptop) {
        $fetchMap['touch'] = {
            Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue |
                Where-Object { $_.Status -eq 'OK' -and $_.FriendlyName -match 'touch screen|HID-compliant touch screen' }
        }
        $fetchMap['monitorSize'] = {
            Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorBasicDisplayParams -ErrorAction SilentlyContinue |
                Select-Object -First 1
        }
        $fetchMap['monitorModes'] = {
            Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorListedSupportedSourceModes -ErrorAction SilentlyContinue
        }
        $fetchMap['battery'] = {
            # Inline BatteryInfoView probe. Returns @{ Percent; FullCapMwh; DesignCapMwh; CurrentChargePct; Diag }.
            $bivPath = Join-Path $env:TEMP 'SystemInfo-BIV.exe'
            $result  = [PSCustomObject]@{ Percent=$null; FullCapMwh=$null; DesignCapMwh=$null; CurrentChargePct=$null; Diag=$null }
            if (-not (Test-Path $bivPath)) { $result.Diag = 'BatteryInfoView not extracted'; return $result }
            $xmlPath = Join-Path $env:TEMP ("SystemInfo-BIV-" + [Guid]::NewGuid().ToString('N') + ".xml")
            try {
                Start-Process -FilePath $bivPath -ArgumentList @('/sxml', "`"$xmlPath`"") -WindowStyle Hidden -Wait
                if (-not (Test-Path $xmlPath)) { $result.Diag = 'BatteryInfoView produced no output'; return $result }
                $doc = New-Object System.Xml.XmlDocument; $doc.Load($xmlPath)
                $fields = @{}
                foreach ($item in @($doc.SelectNodes('//item'))) {
                    $desc = $item.SelectSingleNode('description')
                    if (-not $desc -or -not $desc.InnerText) { continue }
                    $vals = @()
                    foreach ($v in @($item.SelectNodes('value'))) {
                        if ($v.InnerText -and $v.InnerText.Trim()) { $vals += $v.InnerText.Trim() }
                    }
                    $fields[$desc.InnerText.Trim()] = $vals
                }
                $dV = $fields['Designed Capacity']; $fV = $fields['Full Charged Capacity']
                $hV = $fields['Battery Health'];     $cV = $fields['Current Capacity (in %)']
                if ($dV -and $fV) {
                    $design = 0L; $fullC = 0L
                    foreach ($s in $dV) { $n = ($s -replace '[^\d]',''); if ($n) { $design += [int64]$n } }
                    foreach ($s in $fV) { $n = ($s -replace '[^\d]',''); if ($n) { $fullC  += [int64]$n } }
                    if ($design -gt 0 -and $fullC -gt 0) {
                        $result.DesignCapMwh = [int]$design
                        $result.FullCapMwh   = [int]$fullC
                        $result.Percent      = [Math]::Round(($fullC / $design) * 100, 1)
                    }
                }
                if ($result.Percent -eq $null -and $hV) {
                    $m = [regex]::Match($hV[0], '([0-9]+(?:\.[0-9]+)?)')
                    if ($m.Success) { $result.Percent = [double]$m.Groups[1].Value }
                }
                if ($cV) {
                    $m = [regex]::Match($cV[0], '([0-9]+(?:\.[0-9]+)?)')
                    if ($m.Success) { $result.CurrentChargePct = [int][double]$m.Groups[1].Value }
                }
                if ($result.Percent -eq $null -and $result.CurrentChargePct -eq $null) {
                    $result.Diag = 'BatteryInfoView ran but reported no battery data'
                }
                return $result
            } finally {
                Remove-Item -LiteralPath $xmlPath -ErrorAction SilentlyContinue
            }
        }
    }

    $bg = Start-ParallelFetches $fetchMap

    $report = [System.Collections.ArrayList]::new()
    function _Add {
        param($Property, $Value, [int]$HighlightLevel = 0)
        [void]$report.Add([PSCustomObject]@{
            Property       = $Property
            Value          = [string]$Value
            Highlight      = $HighlightLevel -gt 0
            HighlightLevel = $HighlightLevel
        })
    }

    try {
        $cs   = Get-Fetch $bg 'cs'
        $bios = Get-Fetch $bg 'bios'

        if ($script:IsLaptop) {
            $batInfo = Get-Fetch $bg 'battery'
            if ($batInfo) { $script:BatteryHealthCache = $batInfo }
            _Add 'Battery Health' (Get-Safe { Format-BatteryRowValue } 'N/A (no battery data)')
        }
        _Add 'Manufacturer'  (Get-Safe { $cs.Manufacturer })
        _Add 'Model'         (Get-Safe { $cs.Model })
        _Add 'Serial Number' (Get-Safe { $bios.SerialNumber })
        _Add 'CPU' (Get-Safe {
            $cpu = Get-Fetch $bg 'cpu'
            if ($cpu) { $cpu.Name.Trim() } else { 'Unknown' }
        })

        $gpus = @(Get-Fetch $bg 'gpus')
        $ded = @(); $int = @()
        $vcs = $gpus | Where-Object { $_.Name -and $_.Name -notmatch 'Microsoft Basic|Remote|Virtual|Meta|Parsec' }
        foreach ($vc in $vcs) {
            $n = $vc.Name.Trim()
            if ($n -match 'NVIDIA|GeForce|RTX|GTX|Quadro' -or
                $n -match 'Radeon\s+(RX|Pro|R\d|HD\s+[5-9]\d{3})' -or
                $n -match 'Intel.*\bArc\b.*A\d{3}') { $ded += $n } else { $int += $n }
        }
        _Add 'Dedicated GPU'  $(if ($ded) { $ded -join '; ' } else { 'None' })
        _Add 'Integrated GPU' $(if ($int) { $int -join '; ' } else { 'None' })

        _Add 'Audio' (Get-Safe {
            $sounds = @(Get-Fetch $bg 'sounds')
            if (-not $sounds -or $sounds.Count -eq 0) { return 'Unknown' }
            ($sounds | ForEach-Object {
                if ($_.Manufacturer -and $_.Manufacturer -notmatch 'Microsoft|\(Standard') {
                    "$($_.Name) ($($_.Manufacturer))"
                } else { $_.Name }
            }) -join '; '
        })

        if ($script:IsLaptop) {
            _Add 'Touchscreen' (Get-Safe {
                $touch = Get-Fetch $bg 'touch'
                if ($touch) { 'Yes' } else { 'No' }
            })

            _Add 'Screen size' (Get-Safe {
                $m = Get-Fetch $bg 'monitorSize'
                if ($m -and $m.MaxHorizontalImageSize -and $m.MaxVerticalImageSize) {
                    $wCm = [double]$m.MaxHorizontalImageSize
                    $hCm = [double]$m.MaxVerticalImageSize
                    $inches = [Math]::Sqrt(($wCm*$wCm)+($hCm*$hCm)) / 2.54
                    "{0:N1}`" ({1:N1} cm x {2:N1} cm)" -f $inches, $wCm, $hCm
                } else { 'Unknown' }
            })

            _Add 'Screen max resolution' (Get-Safe {
                $res = $null
                $modes = @(Get-Fetch $bg 'monitorModes')
                if ($modes -and $modes.Count -gt 0) {
                    $best = $modes | ForEach-Object {
                        $_.MonitorSourceModes |
                            Sort-Object { $_.HorizontalActivePixels * $_.VerticalActivePixels } -Descending |
                            Select-Object -First 1
                    } | Sort-Object { $_.HorizontalActivePixels * $_.VerticalActivePixels } -Descending |
                        Select-Object -First 1
                    if ($best) { $res = "{0} x {1}" -f $best.HorizontalActivePixels, $best.VerticalActivePixels }
                }
                if (-not $res) {
                    $vc = $gpus | Where-Object { $_.CurrentHorizontalResolution -gt 0 } | Select-Object -First 1
                    if ($vc) { $res = "{0} x {1} (current)" -f $vc.CurrentHorizontalResolution, $vc.CurrentVerticalResolution }
                }
                $res
            })
        }

        # Storage -- prefer Get-PhysicalDisk (gives SSD/HDD + bus + SMART health);
        # if the Storage Management provider returns nothing (intermittent on
        # some machines), fall back to Win32_DiskDrive with model-name heuristics.
        try {
            $physDisks = @(Get-PhysicalDisk -ErrorAction SilentlyContinue | Sort-Object DeviceId)
            $usingFallback = (-not $physDisks -or $physDisks.Count -eq 0)

            $w32List = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue | Sort-Object Index)

            if ($usingFallback) {
                if (-not $w32List -or $w32List.Count -eq 0) {
                    _Add 'Storage' 'Unknown'
                } else {
                    foreach ($w in $w32List) {
                        $sizeGB = [Math]::Round($w.Size / 1GB, 0)
                        $model  = if ($w.Model) { $w.Model.Trim() } else { 'Unknown disk' }
                        $isUsb  = ($w.InterfaceType -match '^USB' -or $w.MediaType -match 'Removable')
                        $isSsd  = $model -match '\bSSD\b|\bNVMe\b|\bM\.2\b'
                        $isHdd  = $model -match '\bHDD\b|Hard\s*Disk'
                        # Modern fixed disks reporting InterfaceType=SCSI are NVMe in 99% of cases.
                        $isNvme = ($model -match '\bNVMe\b|\bM\.2\b') -or
                                  (-not $isUsb -and $w.InterfaceType -eq 'SCSI' -and $w.MediaType -match 'Fixed')
                        if ($isNvme) { $isSsd = $true }

                        $bus = if     ($isUsb)  { 'USB' }
                               elseif ($isNvme) { 'NVMe' }
                               elseif ($w.InterfaceType -eq 'IDE') { 'SATA' }
                               else             { $w.InterfaceType }
                        $media = if ($isSsd) { 'SSD' } elseif ($isHdd) { 'HDD' } else { '' }
                        $typeDesc = (("$bus $media").Trim())
                        if (-not $typeDesc) { $typeDesc = 'Disk' }
                        # Avoid duplicating tokens already present in the model name
                        if ($model -match [regex]::Escape($typeDesc)) { $typeDesc = '' }
                        $line = "$model -- $sizeGB GB"
                        if ($typeDesc) { $line += " -- $typeDesc" }
                        $line += " -- Health: N/A"
                        _Add "Storage (Disk $($w.Index))" $line
                    }
                }
            } else {
                $w32Map = @{}
                foreach ($w in $w32List) { if ($w) { $w32Map[[int]$w.Index] = $w } }
                foreach ($d in $physDisks) {
                    $sizeGB   = [Math]::Round($d.Size / 1GB, 0)
                    $model    = if ($d.FriendlyName) { $d.FriendlyName.Trim() } else { 'Unknown disk' }
                    $typeDesc = ''
                    switch ($d.MediaType) {
                        'SSD' {
                            switch ($d.BusType) {
                                'NVMe' { $typeDesc = 'NVMe SSD' }
                                'SATA'  { $typeDesc = 'SATA SSD' }
                                'USB'   { $typeDesc = 'USB SSD'  }
                                'SCSI'  { $typeDesc = 'SCSI SSD' }
                                'RAID'  { $typeDesc = 'RAID SSD' }
                                default { $typeDesc = "$($d.BusType) SSD" }
                            }
                        }
                        'HDD' {
                            switch ($d.BusType) {
                                'SATA'  { $typeDesc = 'SATA HDD' }
                                'USB'   { $typeDesc = 'USB HDD'  }
                                default { $typeDesc = "$($d.BusType) HDD" }
                            }
                        }
                        default { $typeDesc = "$($d.BusType) $($d.MediaType)" }
                    }
                    $health    = Get-DiskHealthPercent $d
                    $hlLevel   = 0
                    if ($null -ne $health) {
                        $healthStr = "Health: $health%"
                        if ($d.MediaType -eq 'SSD' -and $health -lt 70) { $hlLevel = 2 }
                    } else {
                        $healthStr = "Health: N/A"
                    }
                    _Add "Storage (Disk $($d.DeviceId))" "$model -- $sizeGB GB -- $typeDesc -- $healthStr" -HighlightLevel $hlLevel
                }
            }
        } catch { _Add 'Storage' "Error: $($_.Exception.Message)" }

        _Add 'RAM' (Get-Safe { "{0:N0} GB" -f [Math]::Round($cs.TotalPhysicalMemory / 1GB, 0) })

        _Add 'RAM Slots' (Get-Safe {
            $array      = Get-Fetch $bg 'memArr'
            $totalSlots = if ($array) { [int]$array.MemoryDevices } else { 0 }
            $modules    = @(Get-Fetch $bg 'memMods') | Where-Object { $_ }
            $populated  = @($modules).Count
            $looksSoldered = $false
            foreach ($m in $modules) {
                if ($m.FormFactor -eq 11 -or $m.DeviceLocator -match 'onboard|soldered|system\s*board') {
                    $looksSoldered = $true; break
                }
            }
            $typeMap = @{20='DDR';21='DDR2';24='DDR3';26='DDR4';34='DDR5';27='FBD2';
                         30='LPDDR';31='LPDDR2';32='LPDDR3';33='LPDDR4';35='LPDDR5'}
            $formMap = @{8='DIMM';11='Row-of-chips (soldered)';12='SODIMM';13='SRIMM';15='FB-DIMM'}
            $slotLines = foreach ($m in $modules) {
                $sizeGB = [Math]::Round($m.Capacity / 1GB, 0)
                $type   = if ($typeMap.ContainsKey([int]$m.SMBIOSMemoryType)) { $typeMap[[int]$m.SMBIOSMemoryType] } else { "Type$($m.SMBIOSMemoryType)" }
                $form   = if ($formMap.ContainsKey([int]$m.FormFactor))       { $formMap[[int]$m.FormFactor] }       else { "Form$($m.FormFactor)" }
                $speed  = if ($m.ConfiguredClockSpeed) { "$($m.ConfiguredClockSpeed) MT/s" } elseif ($m.Speed) { "$($m.Speed) MT/s" } else { '' }
                $loc    = if ($m.DeviceLocator) { $m.DeviceLocator.Trim() } else { 'Slot?' }
                "[$loc] ${sizeGB} GB $type $form $speed".TrimEnd()
            }
            $header = "$totalSlots slot(s), $populated populated"
            if ($totalSlots -gt $populated) { $header += ", $($totalSlots - $populated) empty" }
            if ($looksSoldered) { $header += " (appears soldered)" }
            $header + "`r`n" + ($slotLines -join "`r`n")
        })

        _Add 'Wi-Fi' (Get-Safe {
            $adapter = Get-Fetch $bg 'wifiAdapter'
            if (-not $adapter) { return 'No Wi-Fi adapter found' }
            $radioTypes = [string](Get-Fetch $bg 'wifiRadio')
            $gen = 'Wi-Fi version unknown'
            if     ($radioTypes -match '802\.11be') { $gen = 'Wi-Fi 7 (802.11be)'   }
            elseif ($radioTypes -match '802\.11ax') { $gen = 'Wi-Fi 6/6E (802.11ax)' }
            elseif ($radioTypes -match '802\.11ac') { $gen = 'Wi-Fi 5 (802.11ac)'   }
            elseif ($radioTypes -match '802\.11n')  { $gen = 'Wi-Fi 4 (802.11n)'    }
            "$gen -- $($adapter.InterfaceDescription)"
        })

        _Add 'Bluetooth' (Get-Safe {
            $bt = Get-Fetch $bg 'btDevice'
            if (-not $bt) { return 'No Bluetooth adapter found' }
            $lmp = $null
            try {
                $prop = Get-PnpDeviceProperty -InstanceId $bt.InstanceId -KeyName $script:PKEY_BtLmp -ErrorAction Stop
                if ($null -ne $prop.Data) { $lmp = [int]$prop.Data }
            } catch {}
            $btVer = switch ($lmp) {
                0  {'Bluetooth 1.0b'}        1  {'Bluetooth 1.1'}           2  {'Bluetooth 1.2'}
                3  {'Bluetooth 2.0 + EDR'}   4  {'Bluetooth 2.1 + EDR'}    5  {'Bluetooth 3.0 + HS'}
                6  {'Bluetooth 4.0'}         7  {'Bluetooth 4.1'}           8  {'Bluetooth 4.2'}
                9  {'Bluetooth 5.0'}         10 {'Bluetooth 5.1'}           11 {'Bluetooth 5.2'}
                12 {'Bluetooth 5.3'}         13 {'Bluetooth 5.4'}
                default { if ($null -ne $lmp) { "Bluetooth (LMP $lmp)" } else { 'Bluetooth version unknown' } }
            }
            "$btVer -- $($bt.FriendlyName)"
        })

        _Add 'WWAN' (Get-Safe {
            $a = Get-Fetch $bg 'wwanAdapter'
            if ($a) { "Yes -- $($a.InterfaceDescription)" } else { 'Not present' }
        } 'Not present')

        _Add 'Operating System' (Get-Safe {
            $o       = Get-Fetch $bg 'os'
            $caption = $o.Caption.Trim()
            if ($o.BuildNumber -ge 22000 -and $caption -notmatch '11') {
                $caption = $caption -replace 'Windows 10', 'Windows 11'
            }
            $activation = Format-LicenseStatus (Get-Fetch $bg 'license')
            "{0} (Version {1}, Build {2}) -- {3}" -f $caption, $o.Version, $o.BuildNumber, $activation
        })

        # Driver / device health check
        $problemDevs = @(@(Get-Fetch $bg 'pnpProblems') | Where-Object { $_ })
        if ($problemDevs.Count -gt 0) {
            $devList = ($problemDevs | Select-Object -First 5 | ForEach-Object { $_.Name }) -join '; '
            if ($problemDevs.Count -gt 5) { $devList += " (+$($problemDevs.Count - 5) more)" }
            _Add 'Problem Devices' "$($problemDevs.Count) device(s) with driver issues: $devList" -HighlightLevel 1
        } else {
            _Add 'Problem Devices' 'No driver issues detected'
        }

        return ,$report.ToArray()
    } finally {
        Close-Fetches $bg
    }
}

function Format-ReportAsText {
    param($Report)
    $labelWidth = ($Report | ForEach-Object { $_.Property.Length } | Measure-Object -Maximum).Maximum
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("System Information Report")
    [void]$sb.AppendLine("Generated: $(Get-Date)")
    [void]$sb.AppendLine("Computer:  $env:COMPUTERNAME")
    [void]$sb.AppendLine(("=" * 60))
    foreach ($item in $Report) {
        $label = $item.Property.PadRight($labelWidth)
        $lines = $item.Value -split "`r?`n"
        [void]$sb.AppendLine("$label : $($lines[0])")
        if ($lines.Count -gt 1) {
            $indent = ' ' * ($labelWidth + 3)
            for ($i = 1; $i -lt $lines.Count; $i++) { [void]$sb.AppendLine("$indent$($lines[$i])") }
        }
    }
    $sb.ToString()
}

# ==============================================================================
#  AUDIO  (panned tone generator for speaker test)
# ==============================================================================
function New-PannedToneFile {
    param(
        [string]$Path,
        [int]$Frequency = 600,
        [int]$DurationMs = 900,
        [ValidateSet('Left','Right','Both')] [string]$Channel = 'Both'
    )
    $sampleRate    = 44100
    $channels      = 2
    $bitsPerSample = 16
    $totalSamples  = [int]($sampleRate * $DurationMs / 1000)
    $dataSize      = $totalSamples * $channels * 2

    $fs = [System.IO.File]::Create($Path)
    $bw = New-Object System.IO.BinaryWriter($fs)
    try {
        $bw.Write([System.Text.Encoding]::ASCII.GetBytes('RIFF'))
        $bw.Write([uint32](36 + $dataSize))
        $bw.Write([System.Text.Encoding]::ASCII.GetBytes('WAVE'))
        $bw.Write([System.Text.Encoding]::ASCII.GetBytes('fmt '))
        $bw.Write([uint32]16); $bw.Write([uint16]1)
        $bw.Write([uint16]$channels); $bw.Write([uint32]$sampleRate)
        $bw.Write([uint32]($sampleRate * $channels * 2))
        $bw.Write([uint16]($channels * 2)); $bw.Write([uint16]$bitsPerSample)
        $bw.Write([System.Text.Encoding]::ASCII.GetBytes('data'))
        $bw.Write([uint32]$dataSize)
        $amp = 16000; $twoPiF = 2 * [Math]::PI * $Frequency
        $fadeSamples = [int]($sampleRate * 0.025)
        for ($i = 0; $i -lt $totalSamples; $i++) {
            $env = 1.0
            if ($i -lt $fadeSamples)                     { $env = $i / $fadeSamples }
            elseif ($i -gt $totalSamples - $fadeSamples) { $env = ($totalSamples - $i) / $fadeSamples }
            $val = [int16]($amp * $env * [Math]::Sin($twoPiF * $i / $sampleRate)); $silence = [int16]0
            switch ($Channel) {
                'Left'  { $bw.Write($val);    $bw.Write($silence) }
                'Right' { $bw.Write($silence); $bw.Write($val) }
                'Both'  { $bw.Write($val);    $bw.Write($val) }
            }
        }
    } finally { $bw.Close(); $fs.Close() }
}

# ==============================================================================
#  SELF-UPDATE  (GitHub Releases)
# ==============================================================================
function Invoke-AppUpdate {
    if (-not $script:GitHubOwner -or -not $script:GitHubRepo) {
        [System.Windows.Forms.MessageBox]::Show($form,
            "GitHub repository not configured.`r`n`r`n" +
            "Set `$script:GitHubOwner and `$script:GitHubRepo near the top of the script to enable updates.",
            "Check for Updates", 'OK', 'Information') | Out-Null
        return
    }
    try {
        $statusLabel.Text = "Checking for updates..."
        [System.Windows.Forms.Application]::DoEvents()

        $apiUrl  = "https://api.github.com/repos/$script:GitHubOwner/$script:GitHubRepo/releases/latest"
        $headers = @{ 'User-Agent' = 'SystemInfo-GUI/1.0'; 'Accept' = 'application/vnd.github.v3+json' }
        $release = Invoke-RestMethod -Uri $apiUrl -Headers $headers -ErrorAction Stop
        $latestTag = $release.tag_name -replace '^v', ''

        try {
            $current = [Version]$script:AppVersion
            $latest  = [Version]$latestTag
        } catch {
            [System.Windows.Forms.MessageBox]::Show($form,
                "Could not parse version numbers.`r`nCurrent: $script:AppVersion  Latest: $latestTag",
                "Update", 'OK', 'Warning') | Out-Null
            return
        }

        if ($latest -le $current) {
            [System.Windows.Forms.MessageBox]::Show($form,
                "You are running the latest version (v$script:AppVersion).",
                "Check for Updates", 'OK', 'Information') | Out-Null
            $statusLabel.Text = "Already up to date (v$script:AppVersion)."
            return
        }

        $r = [System.Windows.Forms.MessageBox]::Show($form,
            "Update available: v$latestTag`r`nCurrent version: v$script:AppVersion`r`n`r`nDownload and install now?",
            "Update Available", 'YesNo', 'Question')
        if ($r -ne 'Yes') { $statusLabel.Text = "Update skipped."; return }

        # Find asset (.exe preferred, .ps1 fallback)
        $asset = $release.assets | Where-Object { $_.name -like '*.exe' } | Select-Object -First 1
        if (-not $asset) { $asset = $release.assets | Where-Object { $_.name -like '*.ps1' } | Select-Object -First 1 }
        if (-not $asset) {
            [System.Windows.Forms.MessageBox]::Show($form,
                "No downloadable .exe or .ps1 found in the release.",
                "Update", 'OK', 'Warning') | Out-Null
            return
        }

        $statusLabel.Text = "Downloading $($asset.name) ($([Math]::Round($asset.size/1KB,0)) KB)..."
        [System.Windows.Forms.Application]::DoEvents()

        $currentExe = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $tempPath   = $currentExe + '.new'
        $oldPath    = $currentExe + '.old'

        try {
            $wc = New-Object System.Net.WebClient
            $wc.Headers.Add('User-Agent', 'SystemInfo-GUI/1.0')
            $wc.DownloadFile($asset.browser_download_url, $tempPath)
            $wc.Dispose()
        } catch {
            Remove-Item $tempPath -ErrorAction SilentlyContinue
            throw "Download failed: $($_.Exception.Message)"
        }

        # Basic PE validation for .exe
        if ($asset.name -like '*.exe') {
            $bytes = [System.IO.File]::ReadAllBytes($tempPath)
            if ($bytes.Length -lt 2 -or $bytes[0] -ne 0x4D -or $bytes[1] -ne 0x5A) {
                Remove-Item $tempPath -ErrorAction SilentlyContinue
                throw "Downloaded file failed validation (not a valid PE executable)."
            }
        }

        # Rename-and-swap
        try {
            if (Test-Path $oldPath) { Remove-Item $oldPath -Force -ErrorAction Stop }
            Move-Item $currentExe $oldPath -Force -ErrorAction Stop
            Move-Item $tempPath $currentExe -Force -ErrorAction Stop
        } catch {
            # Rollback
            if ((Test-Path $oldPath) -and -not (Test-Path $currentExe)) {
                try { Move-Item $oldPath $currentExe -Force } catch {}
            }
            Remove-Item $tempPath -ErrorAction SilentlyContinue
            throw "Could not replace executable: $($_.Exception.Message)"
        }

        [System.Windows.Forms.MessageBox]::Show($form,
            "Updated to v$latestTag successfully. The application will now restart.",
            "Update Complete", 'OK', 'Information') | Out-Null

        Start-Process $currentExe
        $form.Close()

    } catch {
        [System.Windows.Forms.MessageBox]::Show($form,
            "Update failed:`r`n`r`n$($_.Exception.Message)",
            "Update", 'OK', 'Error') | Out-Null
        $statusLabel.Text = "Update check failed."
    }
}

# ==============================================================================
#  FORM
# ==============================================================================
$baseFont   = New-Object System.Drawing.Font('Segoe UI', 10.5)
$titleFont  = New-Object System.Drawing.Font('Segoe UI Semibold', 16)
$headerFont = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
$propFont   = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
$valFont    = New-Object System.Drawing.Font('Consolas', 10.5)

$form = New-Object System.Windows.Forms.Form
$form.Text          = if (Test-IsAdmin) { "System Information (Administrator)" } else { "System Information" }
$form.Size          = New-Object System.Drawing.Size(960, 820)
$form.StartPosition = 'CenterScreen'
$form.MinimumSize   = New-Object System.Drawing.Size(740, 620)
$form.Font          = $baseFont

# -- Header --------------------------------------------------------------------
$header = New-Object System.Windows.Forms.Panel
$header.Dock      = 'Top'
$header.Height    = 60
$header.BackColor = [System.Drawing.Color]::FromArgb(30, 64, 102)
$form.Controls.Add($header)

$titleLabel = New-Object System.Windows.Forms.Label
$titleLabel.Text      = "System Information Report"
$titleLabel.ForeColor = [System.Drawing.Color]::White
$titleLabel.Font      = $titleFont
$titleLabel.AutoSize  = $true
$titleLabel.Location  = New-Object System.Drawing.Point(18, 14)
$header.Controls.Add($titleLabel)

# -- Button panel (right side) ------------------------------------------------
$buttons = New-Object System.Windows.Forms.FlowLayoutPanel
$buttons.Dock          = 'Right'
$buttons.Width         = 172
$buttons.Padding       = New-Object System.Windows.Forms.Padding(6, 8, 6, 8)
$buttons.FlowDirection = 'TopDown'
$buttons.WrapContents  = $false
$buttons.AutoScroll    = $true
$buttons.BackColor     = [System.Drawing.Color]::FromArgb(245, 246, 250)
$form.Controls.Add($buttons)

function New-ActionButton {
    param([string]$Text)
    $b = New-Object System.Windows.Forms.Button
    $b.Text   = $Text
    $b.Size   = New-Object System.Drawing.Size(156, 32)
    $b.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, 4)
    $b.Font   = $baseFont
    return $b
}

$btnRefresh       = New-ActionButton "Refresh"
$btnBattery       = New-ActionButton "Battery Report"
$btnSpeakers      = New-ActionButton "Test Speakers"
$btnCamera        = New-ActionButton "Test Camera"
$btnKeyboard      = New-ActionButton "Test Keyboard"
$btnDisplay       = New-ActionButton "Test Display"
$btnUpdateDrivers = New-ActionButton "Update Drivers"
$btnCheckUpdates  = New-ActionButton "Check for Updates"
