$qrPanel.Dock      = 'Right'
$qrPanel.Width     = 220
$qrPanel.BackColor = [System.Drawing.Color]::White
$qrPanel.Padding   = New-Object System.Windows.Forms.Padding(10, 10, 10, 10)
