$grid.Columns[1].AutoSizeMode              = 'Fill'
$grid.Columns[1].DefaultCellStyle.WrapMode = 'True'
$grid.Columns[1].DefaultCellStyle.Font     = $valFont

$contentPanel.Controls.Add($grid)
$grid.BringToFront()

# ==============================================================================
#  ACTIONS
# ==============================================================================
$script:currentReport = $null
$script:lastSpecJson  = $null

function Resize-FormToContent {
    if ($grid.Rows.Count -eq 0) { return }
    [System.Windows.Forms.Application]::DoEvents()
    $rowsHeight = 0
    foreach ($row in $grid.Rows) { $rowsHeight += $row.Height }
    $gridNeeded   = $rowsHeight + $grid.ColumnHeadersHeight + 4
    $chrome       = $form.Height - $form.ClientSize.Height
    # Vertical stack on the form is: header (Top) + contentPanel (Fill) + status (Bottom).
    # $buttons is docked Right, so it shares vertical space with contentPanel -- don't add its height.
    # Inside contentPanel: grid (Fill) + qrPanel (Right, no vertical contribution).
    $targetClient = $header.Height + $status.Height + $gridNeeded
    $targetForm   = $targetClient + $chrome
    $screen       = [System.Windows.Forms.Screen]::FromControl($form).WorkingArea
    $newH         = [Math]::Max($form.MinimumSize.Height, [Math]::Min($targetForm, $screen.Height - 40))
    if ($newH -ne $form.Height) {
        $top = $form.Top
        if (($top + $newH) -gt ($screen.Top + $screen.Height)) {
            $top = [Math]::Max($screen.Top, $screen.Top + $screen.Height - $newH)
        }
        $form.SetBounds($form.Left, $top, $form.Width, $newH)
    }
}

function New-CrispQRBitmap {
    # Build a crisp QR for $json sized to about $targetPx: render a 1px-per-module
    # source, then scale it up by an INTEGER factor with nearest-neighbour so the
    # module edges stay razor-sharp. Bilinear/Zoom scaling blurs the modules and a
    # phone camera can't read them off a screen — which is exactly why a QR that
    # decodes fine as a saved image may refuse to scan live. Returns $null if
    # there's nothing to encode.
    param([string]$json, [int]$targetPx)
    if (-not $json) { return $null }
    [void](Get-QRCoderAssembly)
    $qrData = (New-Object QRCoder.QRCodeGenerator).CreateQrCode($json, [QRCoder.QRCodeGenerator+ECCLevel]::M)
    $src    = (New-Object QRCoder.QRCode $qrData).GetGraphic(1)
    $mods   = $src.Width
    $scale  = [Math]::Max(2, [Math]::Floor($targetPx / $mods))
    $px     = $mods * $scale
    $bmp    = New-Object System.Drawing.Bitmap $px, $px
    $g      = [System.Drawing.Graphics]::FromImage($bmp)
    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
    $g.PixelOffsetMode   = [System.Drawing.Drawing2D.PixelOffsetMode]::Half
    $g.DrawImage($src, 0, 0, $px, $px)
    $g.Dispose(); $src.Dispose()
    return $bmp
}

function Update-QRCode {
    # Regenerate the always-visible spec QR thumbnail from the current report.
    # Rendered entirely offline via the embedded QRCoder library; specs never
    # leave the box. Tapping it opens a large version for easy scanning.
    try {
        $old = $qrPicture.Image
        $script:lastSpecJson = $null
        if (-not $script:currentReport) { $qrPicture.Image = $null; if ($old) { $old.Dispose() }; return }
        $json = Get-SpecsJson $script:currentReport
        if (-not $json) {
            $qrPicture.Image = $null; if ($old) { $old.Dispose() }
            $qrCaption.Text = "No spec fields to encode"
            return
        }
        $script:lastSpecJson = $json
        $avail = [Math]::Min($qrPicture.ClientSize.Width, $qrPicture.ClientSize.Height)
        if ($avail -lt 80) { $avail = 200 }   # not laid out yet — assume the panel size
        $qrPicture.Image = New-CrispQRBitmap $json $avail
        $qrCaption.Text  = "Tap the QR to enlarge for scanning"
        if ($old) { $old.Dispose() }
    } catch {
        $qrCaption.Text = "QR unavailable"
    }
}

function Show-QRDialog {
    # Pop a large, crisp QR (~8px per module) so a phone scans it effortlessly.
    if (-not $script:lastSpecJson) { return }
    $big = New-CrispQRBitmap $script:lastSpecJson 560
    if (-not $big) { return }
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text            = "Scan specs"
    $dlg.StartPosition   = 'CenterParent'
    $dlg.FormBorderStyle = 'FixedDialog'
    $dlg.MaximizeBox     = $false
    $dlg.MinimizeBox     = $false
    $dlg.BackColor       = [System.Drawing.Color]::White
    $dlg.KeyPreview      = $true
    $dlg.ClientSize      = New-Object System.Drawing.Size (($big.Width + 40), ($big.Height + 64))
    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.Image    = $big
    $pb.SizeMode = 'AutoSize'
    $pb.Location = New-Object System.Drawing.Point 20, 20
    $dlg.Controls.Add($pb)
    $cap = New-Object System.Windows.Forms.Label
    $cap.Text      = "Scan with your phone - click anywhere to close"
    $cap.Font      = New-Object System.Drawing.Font('Segoe UI', 9)
    $cap.ForeColor = [System.Drawing.Color]::Gray
    $cap.AutoSize  = $false
    $cap.TextAlign = 'MiddleCenter'
    $cap.SetBounds(20, ($big.Height + 26), $big.Width, 24)
    $dlg.Controls.Add($cap)
    $close = [System.EventHandler]{ $dlg.Close() }
    $dlg.Add_Click($close); $pb.Add_Click($close); $cap.Add_Click($close)
    $dlg.Add_KeyDown({ if ($_.KeyCode -eq 'Escape') { $dlg.Close() } })
    $dlg.ShowDialog($form) | Out-Null
    $big.Dispose(); $dlg.Dispose()
}

function Populate-Grid {
    $statusLabel.Text   = "Gathering system information..."
    $form.Cursor        = [System.Windows.Forms.Cursors]::WaitCursor
    $btnRefresh.Enabled = $false
    $script:BatteryHealthCache = $null
    [System.Windows.Forms.Application]::DoEvents()
    try {
        $report = Get-SystemReport
        $script:currentReport = $report
        $grid.Rows.Clear()
        $driverProblems = $false
        foreach ($item in $report) {
            $rowIndex = $grid.Rows.Add($item.Property, $item.Value)
            if ($item.HighlightLevel -eq 2) {
                # Red  -  critical (e.g. SSD health)
                $grid.Rows[$rowIndex].DefaultCellStyle.BackColor          = [System.Drawing.Color]::FromArgb(232, 90, 90)
                $grid.Rows[$rowIndex].DefaultCellStyle.ForeColor          = [System.Drawing.Color]::White
                $grid.Rows[$rowIndex].DefaultCellStyle.SelectionBackColor = [System.Drawing.Color]::FromArgb(200, 60, 60)
                $grid.Rows[$rowIndex].DefaultCellStyle.SelectionForeColor = [System.Drawing.Color]::White
            } elseif ($item.HighlightLevel -eq 1) {
                # Orange  -  warning (e.g. driver issues)
                $grid.Rows[$rowIndex].DefaultCellStyle.BackColor          = [System.Drawing.Color]::FromArgb(255, 200, 80)
                $grid.Rows[$rowIndex].DefaultCellStyle.ForeColor          = [System.Drawing.Color]::FromArgb(80, 50, 0)
                $grid.Rows[$rowIndex].DefaultCellStyle.SelectionBackColor = [System.Drawing.Color]::FromArgb(220, 160, 40)
                $grid.Rows[$rowIndex].DefaultCellStyle.SelectionForeColor = [System.Drawing.Color]::Black
                if ($item.Property -eq 'Problem Devices') { $driverProblems = $true }
            }
        }
        Update-QRCode
        Resize-FormToContent
        $msg = "Ready. $($report.Count) items. Last refreshed $(Get-Date -Format 'HH:mm:ss')."
        if ($driverProblems) { $msg += "  ! Driver issues detected  -  see Problem Devices row." }
        $statusLabel.Text = $msg
    } catch {
        [System.Windows.Forms.MessageBox]::Show($form,
            "Error gathering information:`r`n$($_.Exception.Message)", "Error", 'OK', 'Error') | Out-Null
        $statusLabel.Text = "Error: $($_.Exception.Message)"
    } finally {
        $form.Cursor        = [System.Windows.Forms.Cursors]::Default
        $btnRefresh.Enabled = $true
    }
}

$btnRefresh.Add_Click({ Populate-Grid })

$btnBattery.Add_Click({
    # Launch the embedded BatteryInfoView (NirSoft) v1.27 GUI for full
    # interactive battery detail. Empty on a desktop / VM with no battery.
    $statusLabel.Text = "Opening BatteryInfoView..."
    [System.Windows.Forms.Application]::DoEvents()
    $exe = Get-EmbeddedBatteryInfoViewPath
    if (-not $exe) {
        [System.Windows.Forms.MessageBox]::Show($form,
            "BatteryInfoView is not embedded in this build.",
            "Battery Report", 'OK', 'Warning') | Out-Null
        $statusLabel.Text = "BatteryInfoView unavailable."
        return
    }
    try {
        Start-Process -FilePath $exe -WorkingDirectory (Split-Path $exe) -ErrorAction Stop | Out-Null
        $statusLabel.Text = "BatteryInfoView launched."
    } catch {
        [System.Windows.Forms.MessageBox]::Show($form,
            "Could not launch BatteryInfoView.`r`n`r`n$($_.Exception.Message)",
            "Battery Report", 'OK', 'Warning') | Out-Null
        $statusLabel.Text = "BatteryInfoView failed to launch."
    }
})

# -- Speaker test  -  auto-ticks checkbox ---------------------------------------
$btnSpeakers.Add_Click({
    $btnSpeakers.Enabled = $false
    $leftWav  = Join-Path $env:TEMP ("spk-L-{0}.wav" -f ([Guid]::NewGuid().ToString('N')))
    $rightWav = Join-Path $env:TEMP ("spk-R-{0}.wav" -f ([Guid]::NewGuid().ToString('N')))
    try {
        New-PannedToneFile -Path $leftWav  -Channel Left  -Frequency 600 -DurationMs 900
        New-PannedToneFile -Path $rightWav -Channel Right -Frequency 800 -DurationMs 900
        $player = New-Object System.Media.SoundPlayer
        $statusLabel.Text = "Speaker test: playing LEFT speaker..."
        [System.Windows.Forms.Application]::DoEvents()
        $player.SoundLocation = $leftWav;  $player.Load(); $player.PlaySync()
        Start-Sleep -Milliseconds 350
        $statusLabel.Text = "Speaker test: playing RIGHT speaker..."
        [System.Windows.Forms.Application]::DoEvents()
        $player.SoundLocation = $rightWav; $player.Load(); $player.PlaySync()
        $statusLabel.Text = "Speaker test complete. [OK]"
    } catch {
        [System.Windows.Forms.MessageBox]::Show($form, "Speaker test failed:`r`n$($_.Exception.Message)",
            "Speaker Test", 'OK', 'Error') | Out-Null
        $statusLabel.Text = "Speaker test failed."
    } finally {
        Remove-Item $leftWav, $rightWav -ErrorAction SilentlyContinue
        $btnSpeakers.Enabled = $true
    }
})

# -- Camera test  -  auto-ticks checkbox ----------------------------------------
$btnCamera.Add_Click({
    $statusLabel.Text = "Opening Camera app..."
    try {
        Start-Process "microsoft.windows.camera:" -ErrorAction Stop
        $statusLabel.Text = "Camera app launched. [OK]"
    } catch {
