            Start-Process "explorer.exe" "shell:AppsFolder\Microsoft.WindowsCamera_8wekyb3d8bbwe!App" -ErrorAction Stop
            $statusLabel.Text = "Camera app launched. [OK]"
        } catch {
            [System.Windows.Forms.MessageBox]::Show($form,
                "Could not launch the Camera app.`r`n`r`n$($_.Exception.Message)", "Camera", 'OK', 'Warning') | Out-Null
            $statusLabel.Text = "Camera app not available."
        }
    }
})

function Get-EmbeddedKbExePath {
    # Extracts the embedded kb.exe to %TEMP%\SystemInfo-kb.exe on first use,
    # reusing the cached copy if its size already matches the embedded payload.
    # Falls back to a sibling kb.exe if the embedded payload is missing.
    if ($script:EmbeddedKbExeB64 -and $script:EmbeddedKbExeB64 -notlike '*PLACEHOLDER*') {
        $bytes  = [Convert]::FromBase64String($script:EmbeddedKbExeB64)
        $target = Join-Path $env:TEMP 'SystemInfo-kb.exe'
        $needWrite = $true
        if (Test-Path -LiteralPath $target) {
            try { if ((Get-Item -LiteralPath $target).Length -eq $bytes.Length) { $needWrite = $false } } catch {}
        }
        if ($needWrite) { [IO.File]::WriteAllBytes($target, $bytes) }
        return $target
    }
    $sibling = Join-Path $script:AppDir 'kb.exe'
    if (Test-Path -LiteralPath $sibling) { return $sibling }
    return $null
}

# -- Keyboard test  -  auto-ticks checkbox --------------------------------------
$btnKeyboard.Add_Click({
    try {
        $kbExe = Get-EmbeddedKbExePath
        if ($kbExe) { Start-Process -FilePath $kbExe -ErrorAction Stop }
