    } catch {
        [System.Windows.Forms.MessageBox]::Show($form,
            "Could not launch the keyboard tester.`r`n`r`n$($_.Exception.Message)",
            "Keyboard Test", 'OK', 'Warning') | Out-Null
        $statusLabel.Text = "Keyboard tester failed to launch."
    }
})

