})
# -- Update Drivers ------------------------------------------------------------
$btnUpdateDrivers.Add_Click({
    $hasModule = Get-Module -Name PSWindowsUpdate -ListAvailable -ErrorAction SilentlyContinue
    if (-not $hasModule) {
        $r = [System.Windows.Forms.MessageBox]::Show($form,
            "The PSWindowsUpdate module is required for driver updates but is not installed.`r`n`r`nInstall it now? (Requires internet access, may take a moment)",
            "Update Drivers", 'YesNo', 'Question')
        if ($r -ne 'Yes') { return }
        $statusLabel.Text = "Installing PSWindowsUpdate module..."
        [System.Windows.Forms.Application]::DoEvents()
        try {
            Start-Process powershell.exe -ArgumentList @(
                '-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command',
                'Install-Module PSWindowsUpdate -Force -Scope CurrentUser; Write-Host "Done. Press any key..."; $null = $host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")'
            ) -Verb RunAs -Wait -ErrorAction Stop
        } catch {
            [System.Windows.Forms.MessageBox]::Show($form,
                "Could not install PSWindowsUpdate:`r`n$($_.Exception.Message)", "Update Drivers", 'OK', 'Error') | Out-Null
            $statusLabel.Text = "PSWindowsUpdate install failed."
            return
        }
    }

    $r2 = [System.Windows.Forms.MessageBox]::Show($form,
        "This will search Windows Update for driver updates and install them.`r`n`r`nThe process runs in a separate window. The PC may restart automatically if required.`r`n`r`nProceed?",
        "Update Drivers", 'YesNo', 'Question')
    if ($r2 -ne 'Yes') { return }

    Start-Process powershell.exe -ArgumentList @(
        '-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command',
        'Import-Module PSWindowsUpdate; Get-WindowsUpdate -Category "Drivers" -Install -AcceptAll -Verbose; Write-Host "`nDone. Press any key to close..."; $null = $host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")'
    ) -Verb RunAs -ErrorAction SilentlyContinue

    $statusLabel.Text = "Driver update launched in separate window."
})

# -- Check for Updates ---------------------------------------------------------
$btnCheckUpdates.Add_Click({ Invoke-AppUpdate })

# -- Close ---------------------------------------------------------------------
$btnClose.Add_Click({ $form.Close() })

# ==============================================================================
$form.Add_Shown({ Populate-Grid })
[void]$form.ShowDialog()
$form.Dispose()
